{
  "version": 1,
  "hooks": {
    "beforeSubmitPrompt": [
      {
        "command": "/opt/node <HOME>/.local/share/khala/npm/lib/node_modules/khala-cli/dist/khala.mjs hook deliver --harness cursor",
        "timeout": 10
      }
    ],
    "postToolUse": [
      {
        "command": "/opt/node <HOME>/.local/share/khala/npm/lib/node_modules/khala-cli/dist/khala.mjs hook deliver --harness cursor",
        "timeout": 10
      }
    ],
    "stop": [
      {
        "command": "/opt/node <HOME>/.local/share/khala/npm/lib/node_modules/khala-cli/dist/khala.mjs hook deliver --harness cursor",
        "timeout": 10
      }
    ]
  }
}
